import { type SerializedError } from './errors';
import { type Theme } from './config';
/**
 * ============================================
 * 通信方向：host => iframe
 * ============================================
 */
/**
 * 初始化消息
 *
 * 用于 host 向 iframe 发送初始化配置
 */
export interface InitMessage {
    type: 'INIT';
    payload: {
        /**
         * 项目 ID
         */
        projectId: string;
        /**
         * 访问令牌
         */
        token: string;
        /**
         * 主题模式
         * @default 'light'
         */
        theme?: Theme;
        /**
         * 无权限访问描述
         */
        unauthorizedDescription?: string;
    };
}
/**
 * 更新配置消息
 *
 * 用于 host 向 iframe 发送配置更新
 */
export interface UpdateConfigMessage {
    type: 'UPDATE_CONFIG';
    payload: {
        /**
         * 主题模式
         */
        theme?: Theme;
    };
}
/**
 * 更新令牌消息
 *
 * 用于 host 向 iframe 发送新的访问令牌
 */
export interface UpdateTokenMessage {
    type: 'UPDATE_TOKEN';
    payload: {
        /**
         * 新的访问令牌
         */
        token: string;
    };
}
/**
 * host 向 iframe 发送的所有消息类型联合
 */
export type OnEventMessage = InitMessage | UpdateConfigMessage | UpdateTokenMessage;
/**
 * ============================================
 * 通信方向：iframe => host
 * ============================================
 */
/**
 * iframe 加载完成消息
 *
 * iframe 加载完成后发送此消息通知 host
 */
export interface IframeReadyMessage {
    type: 'IFRAME_READY';
    payload: {};
}
/**
 * iframe 销毁消息
 *
 * iframe 即将销毁时发送此消息通知 host
 */
export interface IframeDestroyMessage {
    type: 'IFRAME_DESTROY';
    payload: {};
}
/**
 * 项目信息加载完成消息
 *
 * iframe 加载完成后发送此消息通知 host 项目信息加载完成
 */
export interface ProjectInfoLoadedMessage {
    type: 'PROJECT_INFO_LOADED';
    payload: {
        projectId: string;
        name: string;
        description?: string;
        iconUrl: string;
        creatorInfo: {
            avatarUrl: string;
            userUniqueName: string;
            userId: string;
            nickname: string;
        };
        projectType: string;
    };
}
/**
 * 令牌过期消息
 *
 * 当访问令牌过期时，iframe 发送此消息通知 host 需要更新令牌
 */
export interface TokenExpiredMessage {
    type: 'TOKEN_EXPIRED';
    payload: {};
}
/**
 * 令牌不合法消息
 *
 * 当访问令牌验证失败时，iframe 发送此消息通知 host
 */
export interface TokenInvalidMessage {
    type: 'TOKEN_INVALID';
    payload: {};
}
/**
 * 网络错误消息
 *
 * 当发生网络错误时，iframe 发送此消息通知 host
 */
export interface NetworkErrorMessage {
    type: 'NETWORK_ERROR';
    payload: {
        /**
         * 序列化后的错误对象
         */
        error: SerializedError;
    };
}
/**
 * 通知消息
 *
 * 用于 iframe 向 host 发送各类通知事件
 */
export interface NotifyMessage {
    type: 'NOTIFY';
    payload: {
        /**
         * 通知级别
         */
        level: 'error' | 'warn' | 'info';
        /**
         * 通知消息内容
         */
        message: string;
        /**
         * 其他自定义字段
         */
        [key: string]: any;
    };
}
/**
 * iframe 向 host 发送的所有消息类型联合
 */
export type SendEventMessage = IframeReadyMessage | IframeDestroyMessage | ProjectInfoLoadedMessage | TokenExpiredMessage | TokenInvalidMessage | NetworkErrorMessage | NotifyMessage;
/**
 * 所有事件消息的类型字符串联合
 */
export type EventMessageType = (OnEventMessage | SendEventMessage)['type'];
/**
 * 根据消息类型获取对应的 payload 类型
 *
 * @template T - 消息类型字符串
 */
export type EventMessagePayloadOf<T extends (OnEventMessage | SendEventMessage)['type']> = Extract<OnEventMessage | SendEventMessage, {
    type: T;
}>['payload'];
